package com.eugenia.orders.domain;
import org.junit.jupiter.api.Test; import java.math.BigDecimal; import java.util.List; import static com.eugenia.orders.domain.OrderModels.*; import static org.assertj.core.api.Assertions.*;
class PolicyAndValidationTest { @Test void eligibility(){var p=new EligibilityPolicy();assertThat(p.rejectionReason(Market.MX,new Client("C",false,Segment.RETAIL,TaxRegime.GENERAL,Market.MX),List.of())).contains("CLIENT_BLOCKED");assertThat(p.rejectionReason(Market.MX,new Client("C",true,Segment.RETAIL,TaxRegime.GENERAL,Market.CO),List.of())).contains("CLIENT_MARKET_MISMATCH");} @Test void validation(){var v=new OrderValidator();var items=List.of(new OrderValidator.InputItem("P",1,BigDecimal.ONE),new OrderValidator.InputItem("P",2,BigDecimal.ONE));assertThatThrownBy(()->v.validate(new OrderValidator.Input("E",1,"O",Market.MX,"USD","C",items))).hasMessageContaining("currency");assertThatThrownBy(()->v.validate(new OrderValidator.Input("E",1,"O",Market.MX,"MXN","C",items))).hasMessageContaining("duplicate");} }
